export type ServiceStatus =
  | 'INVALID_ARGUMENT'
  | 'FAILED_PRECONDITION'
  | 'NOT_FOUND'
  | 'PERMISSION_DENIED'
  | 'ALREADY_EXISTS';

export class ProjectCollaborationError extends Error {
  public constructor(
    public readonly status: ServiceStatus,
    public readonly reason: string,
    message: string,
    public readonly fieldViolations: readonly {
      readonly field: string;
      readonly description: string;
    }[] = [],
  ) {
    super(message);
    this.name = 'ProjectCollaborationError';
  }

async function requireMembership(
  projectId: string,
  userId: string,
): Promise<MemberRole> {
  const role = await membershipRole(projectId, userId);
  if (!role) {
    throw new ProjectCollaborationError(
      'PERMISSION_DENIED',
      'PROJECT_ACCESS_DENIED',
      `User ${userId} is not a member of project ${projectId}.`,
    );
  }
  return role;
}

export function toApiError(error: ProjectCollaborationError): ApiError {
  return new ApiError({
    status: error.status,
    reason: error.reason,
    domain: DOMAIN,
    message: error.message,
    fieldViolations:
      error.fieldViolations.length > 0 ? error.fieldViolations : undefined,
  });
}

export const collaborationApiRoutes: AppApiRouteContribution<Application> =
  defineApiRoutes((app) => {
    // The authenticated half is its own router typed with `AuthEnv`; the outer router is what a contribution must
    // return, and it never sees the route handlers.
    const router = new Hono<AuthEnv>();
    const root = new Hono();
    const auth = app.container.resolve(authenticationToken);
    const service = app.container.resolve(projectsServiceToken);

    // Middleware is scoped to the literal segments this router owns so it cannot
    // reach any other contribution mounted at `/api`.
    for (const path of [
      '/projects',
      '/projects/*',
      '/milestones/*',
      '/tasks/*',
      '/deliverables/*',
      '/projectCollaborators',
    ]) {
      router.use(path, auth.required());
    }

    root.onError((error, context) =>
      apiErrorHandler(
        error instanceof ProjectCollaborationError ? toApiError(error) : error,
        context,
      ),
    );

/**
 * The content route answers the same domain errors as the collaboration API; without this translation a
 * `ProjectCollaborationError` (for example a member who is neither the submitter, the owner, nor a share holder) is
 * not recognized by `apiErrorHandler`, which rethrows it and turns a permission denial into an opaque 500.
 */
function mapDomainError(error: unknown): unknown {
  return error instanceof ProjectCollaborationError ? toApiError(error) : error;
}

